const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const aoi = ee.Geometry.Rectangle([65, 35, 72, 38]); // Northern Afghanistan

  const baselineStartDate = '2000-06-01';
  const baselineEndDate = '2013-08-31';
  const comparisonStartDate = '2018-06-01';
  const comparisonEndDate = '2018-08-31';

  // Define MODIS collection and bands
  const modisCollection = ee.ImageCollection('MODIS/061/MOD13A2');
  const ndviBand = 'NDVI';
  const qaBand = 'SummaryQA';

  // 2. Data Acquisition & Processing
  const maskModisQA = function(image) {
    // Select the QA band
    const qa = image.select(qaBand);
    // Keep only pixels with the best quality (SummaryQA == 0)
    const qualityMask = qa.eq(0);
    // Unmask NDVI values and apply scale factor
    const ndvi = image.select(ndviBand).multiply(0.0001);
    // Apply the mask to the NDVI band
    return ndvi.updateMask(qualityMask);
  };

  // Get Baseline Data (2000-2013)
  const baselineCollection = modisCollection
    .filterDate(baselineStartDate, baselineEndDate)
    .filter(ee.Filter.calendarRange(6, 8, 'month'))
    .filterBounds(aoi);

  // Get Comparison Data (2018)
  const comparisonCollection = modisCollection
    .filterDate(comparisonStartDate, comparisonEndDate)
    .filterBounds(aoi);

  // 3. Data Availability Check
  const baselineSize = baselineCollection.size().getInfo();
  const comparisonSize = comparisonCollection.size().getInfo();

  if (baselineSize === 0 || comparisonSize === 0) {
    console.log(`Baseline (2000-2013) image count: ${baselineSize}`);
    console.log(`Comparison (2018) image count: ${comparisonSize}`);
    console.log("Empty Collection: No images found for one or both periods.");
    console.log("A"); // C1
    return;
  }
  console.log(`Baseline (2000-2013) image count: ${baselineSize}`);
  console.log(`Comparison (2018) image count: ${comparisonSize}`);

  // 4. Processing and Calculation
  const baselineMean = baselineCollection.map(maskModisQA).mean();
  const comparisonMean = comparisonCollection.map(maskModisQA).mean();

  const scale = 1000; // MODIS 1km data, scale up to avoid timeouts

  // Calculate baseline average NDVI and pixel count
  const baselineStats = baselineMean.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  // Calculate comparison average NDVI and pixel count
  const comparisonStats = comparisonMean.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  const baselineNDVI = baselineStats[ndviBand];
  const baselineCount = baselineStats[`${ndviBand}_count`];

  const comparisonNDVI = comparisonStats[ndviBand];
  const comparisonCount = comparisonStats[`${ndviBand}_count`];

  // 5. Validation and Final Answer
  if (baselineCount === 0 || comparisonCount === 0) {
      console.log(`Baseline valid pixel count: ${baselineCount}`);
      console.log(`Comparison valid pixel count: ${comparisonCount}`);
      console.log("No valid pixels after cloud/QA masking for one or both periods.");
      console.log("B"); // C2
      return;
  }

  console.log(`Baseline (2000-2013) Avg NDVI: ${baselineNDVI.toFixed(4)}, Pixels: ${baselineCount}`);
  console.log(`Comparison (2018) Avg NDVI: ${comparisonNDVI.toFixed(4)}, Pixels: ${comparisonCount}`);

  if (baselineNDVI === null || comparisonNDVI === null || isNaN(baselineNDVI) || isNaN(comparisonNDVI)) {
    console.log("Calculation resulted in null or NaN.");
    console.log("C"); // C3
    return;
  }

  if (comparisonNDVI < baselineNDVI) {
    console.log("NDVI in 2018 was lower than the 2000-2013 average.");
    console.log("A");
  } else {
    console.log("NDVI in 2018 was not lower than the 2000-2013 average.");
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log("D"); // D
});
